CREATE TABLE IF NOT EXISTS account_staking_positions (staking_position_id BIGSERIAL PRIMARY KEY, account_id UUID NOT NULL REFERENCES perpsia_accounts(account_id), wallet_id BIGINT REFERENCES account_wallets(wallet_id), asset_id BIGINT REFERENCES token_assets(asset_id), amount NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(account_id, wallet_id, asset_id));
CREATE TABLE IF NOT EXISTS staking_events (event_id TEXT PRIMARY KEY, account_id UUID NOT NULL REFERENCES perpsia_accounts(account_id), wallet_id BIGINT REFERENCES account_wallets(wallet_id), asset_id BIGINT REFERENCES token_assets(asset_id), event_type TEXT NOT NULL, amount NUMERIC NOT NULL, block_number BIGINT, payload JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS staking_checkpoints (source TEXT PRIMARY KEY, block_number BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS account_entitlements (account_id UUID NOT NULL REFERENCES perpsia_accounts(account_id), tier TEXT NOT NULL, source TEXT NOT NULL, expires_at TIMESTAMPTZ, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(account_id, tier, source));
